void Solver::rephase() {
    // Reset the rephase counter for the next cycle
    rephases = 0;

    // Make the next rephase trigger a bit earlier when the search goes deep
    threshold = static_cast<int>(threshold * 0.85);

    // Grow the rephase limit adaptively – the more conflicts we have seen,
    // the larger the limit, but increase it gradually to avoid too‑frequent rephasing
    rephase_limit += (conflicts / 1000 + 1) * 4096;

    // ---- Phase‑saving strategy -----------------------------------------
    // Mix three simple policies and pick one at random:
    //   1) keep the best polarity seen so far (local_best)
    //   2) invert the best polarity
    //   3) assign a completely random polarity
    int r = rand() % 100;
    if (r < 40) {
        // Use the best polarity observed so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 70) {
        // Invert the best polarity to explore the opposite region
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // Random polarity for diversification
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}
